import {account,emptyWorkspace} from './account.js';
let currentUser=account.getSession(),authMode='signin',authBusy=false;
const icons={orbit:'<ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(-35 12 12)"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(35 12 12)"/><circle cx="12" cy="12" r="2"/>',projects:'<rect x="3" y="4" width="18" height="17" rx="3"/><path d="M3 10h18M9 4v6"/>',creatives:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',activity:'<path d="M20 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 18 0Z"/><path d="M7 10h8M7 14h5"/>',portfolio:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4Z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.orbit}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art=Object.fromEntries(["film","music","light","city","studio","camera"].map(k=>[k,`./covers/${k}.svg`]));
const roles=['Director','Producer','Screenwriter','Cinematographer','Camera operator','Gaffer','Production designer','Actor','Voice actor','Editor','Colorist','VFX artist','Animator','Composer','Music producer','Musician','Vocalist','Sound designer','Foley artist','Location sound recordist','Mixing engineer','Mastering engineer'];
const projects=[{id:'hollow',title:'Hollow Signal',medium:'Film',stage:'Post-production',description:'A voice in the static. A city that disappeared. Help us bring an atmospheric sci-fi short to life.',roles:['Composer','Sound designer','VFX artist'],location:'Los Angeles · Remote',budget:'Paid collaboration',cover:art.film,owner:'Sana Khoury'}, {id:'blue',title:'The Blue Hours',medium:'Music',stage:'In production',description:'An intimate, late-night EP built from warm textures, imperfect rhythms, and the sounds between.',roles:['Vocalist','Mixing engineer','Musician'],location:'Remote',budget:'Paid collaboration',cover:art.music,owner:'Julian Obi'}, {id:'light',title:'Where the light lands',medium:'Animation',stage:'In production',description:'One home. Three generations. An animated short about the small things we leave behind.',roles:['Animator','Sound designer','Editor'],location:'Vancouver · Remote',budget:'Creative partnership',cover:art.light,owner:'Rae Aoki'}, {id:'city',title:'People after midnight',medium:'Film',stage:'Pre-production',description:'A documentary portrait of the people who keep a city moving while everyone else is asleep.',roles:['Cinematographer','Location sound recordist','Colorist'],location:'New York',budget:'Paid collaboration',cover:art.city,owner:'Eli Park'}, {id:'room',title:'A room for sound',medium:'Music',stage:'Development',description:'Live sessions celebrating independent voices, recorded together in one very small room.',roles:['Music producer','Camera operator','Editor'],location:'Los Angeles',budget:'Creative partnership',cover:art.studio,owner:'Mira Pelt'}, {id:'frame',title:'In another frame',medium:'Film',stage:'Development',description:'A character-led short about a photographer slowly finding a different way to see.',roles:['Screenwriter','Actor','Gaffer'],location:'London',budget:'Paid collaboration',cover:art.camera,owner:'Sana Khoury'}];
const creatives=[{id:'noor',name:'Noor Vale',roles:['Composer','Sound designer'],location:'Los Angeles · Remote',headline:'Sound for worlds you haven’t seen yet.',bio:'I build intimate scores and detailed sound worlds for independent film and animation.',cover:art.studio,work:'Between the signals',credit:'Original score & sound design'}, {id:'sana',name:'Sana Khoury',roles:['Director','Screenwriter'],location:'London · Remote',headline:'Human stories. Unfamiliar worlds.',bio:'Character-led speculative stories with a little unease. Looking for people who love the details.',cover:art.film,work:'The last station',credit:'Writing & direction'}, {id:'rae',name:'Rae Aoki',roles:['Animator','Production designer'],location:'Vancouver · Remote',headline:'Movement with a point of view.',bio:'Exploring graphic systems, expressive characters, and unexpected ways to tell a story.',cover:art.light,work:'Soft machines',credit:'Art direction & animation'}, {id:'julian',name:'Julian Obi',roles:['Music producer','Mixing engineer','Composer'],location:'Remote',headline:'Rhythm, texture, a little imperfection.',bio:'Warm production and thoughtful mixes for independent artists and filmmakers.',cover:art.music,work:'In motion',credit:'Composition & production'}, {id:'eli',name:'Eli Park',roles:['Editor','Colorist'],location:'Toronto · Remote',headline:'Find the story between the frames.',bio:'Documentary and narrative editing with a focus on pacing, texture, and human connection.',cover:art.camera,work:'People in passing',credit:'Editing & color'}, {id:'mira',name:'Mira Pelt',roles:['Musician','Composer'],location:'San Diego',headline:'Acoustic detail. Cinematic scale.',bio:'String-led scores for emotionally grounded stories. Open to carefully scoped collaborations.',cover:art.city,work:'Paper lanterns',credit:'Composition & strings'}];
const blank={name:'',headline:'',bio:'',roles:[],location:'',works:[]};
let state=currentUser?account.loadWorkspace(currentUser):emptyWorkspace();
let view=['projects','creatives','activity','portfolio'].includes(location.hash.slice(1))?location.hash.slice(1):'projects',query='',category='All projects',role='',savedOnly=false;
const app=document.querySelector('#app'),dialog=document.querySelector('#detail');
function persist(){try{account.saveWorkspace(currentUser,state);return true;}catch{toast('Browser storage is full or unavailable. These changes last for this session only.');return false;}}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function tags(items){return items.map(t=>`<span class="tag">${esc(t)}</span>`).join('');}
function cover(p,cls=''){return `<div class="cover ${cls}"><img src="${esc(p.cover)}" alt="${esc(p.title||p.name)} moodboard" loading="lazy"><span class="cover-label">${esc(p.medium||'Open to collaborate')}</span>${p.medium?`<button class="bookmark ${state.saved.includes(p.id)?'saved':''}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${state.saved.includes(p.id)}" data-save="${p.id}">${icon('bookmark')}</button>`:''}<div class="cover-bottom"><span><i class="dot"></i>${esc(p.stage||p.location)}</span>${p.medium?'<span>↗</span>':''}</div></div>`;}
function projectCard(p){return `<article class="card interactive-card"><button class="card-open" data-project="${p.id}" aria-label="Open ${esc(p.title)}"></button>${cover(p)}<div class="card-body"><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="tags">${tags(p.roles)}</div><div class="card-foot"><span>${esc(p.budget)}</span><button data-project="${p.id}">View project ${icon('arrow')}</button></div></div></article>`;}
function creatorCard(c){return `<article class="card">${cover(c,'creator-cover')}<div class="card-body"><div class="creator-head"><div class="creator-avatar">${esc(c.name.split(' ').map(x=>x[0]).join(''))}</div><div><h3>${esc(c.name)}</h3><p>${esc(c.location)}</p></div></div><p>${esc(c.headline)}</p><div class="tags">${tags(c.roles)}</div><div class="card-foot"><span>Portfolio available</span><button data-creator="${c.id}">Meet ${esc(c.name.split(' ')[0])} ${icon('arrow')}</button></div></div></article>`;}
function render(){if(!currentUser)return renderAuth();document.body.classList.remove("signed-out");const titles={projects:['Find your people.','Make your project.','Discover independent projects and bring your craft to something you believe in.'],creatives:['A little chemistry.','A lot of possibility.','Meet the filmmakers, musicians, and creative minds who could make all the difference.'],activity:['Good things start','with a conversation.','Your project requests and creative invitations, together in one place.'],portfolio:['Your craft.','Your calling card.','Show what you make, the part you played, and what you want to create next.']},t=titles[view];app.innerHTML=`<div class="shell"><header class="topbar"><div class="brand">${icon('orbit')}<span>perception den</span></div><div class="top-actions"><button type="button" class="secondary sign-out" data-sign-out>Sign out</button><button class="primary" data-action="create">${icon('plus')} New project</button><button class="round avatar" data-nav="portfolio" aria-label="Your portfolio">${esc((state.profile.name||'You').slice(0,2).toUpperCase())}</button></div></header><main><section class="hero"><div><p class="eyebrow">A space for independent creators</p><h1>${t[0]}<br><em>${t[1]}</em></h1></div><p class="intro">${t[2]}</p></section>${view==='projects'||view==='creatives'?`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Search ${view}" placeholder="${view==='projects'?'Search projects, stories, or roles…':'Search people, skills, or location…'}" value="${esc(query)}"></label><button class="filter mobile-role-filter" type="button" data-open-role-filter aria-haspopup="dialog" aria-controls="mobile-role-dialog"><span>${esc(role||"All creative roles")}</span><span aria-hidden="true">⌄</span></button><select id="role" class="filter desktop-role-filter" aria-label="Filter by creative role"><option value="">All creative roles</option>${roles.map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select>${view==='projects'?`<button class="round ${savedOnly?'avatar':''}" data-action="saved" aria-label="Show saved projects" aria-pressed="${savedOnly}">${icon('bookmark')}</button>`:''}</div>${view==='projects'?`<div class="chips">${['All projects','Film','Music','Animation','My projects'].map(c=>`<button class="chip ${category===c?'active':''}" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div>`:''}<div class="section-title"><h2>${view==='projects'?'Find your next project':'People worth making things with'}</h2><span id="count"></span></div><div id="results" class="grid"></div>${view==='projects'?`<section class="banner"><div><h2>Your idea is someone’s next great project.</h2><p>Put it out there. Find the people who see what you see.</p></div><button class="primary" data-action="create">Start a project ${icon('arrow')}</button></section>`:''}`:view==='portfolio'?portfolio():activity()}${view==='portfolio'?myProjects():''}<p class="demo-note">Frontend preview · Sample community · Your changes stay in this browser</p></main></div><nav class="bottom-nav" aria-label="Main navigation">${['projects','creatives','activity','portfolio'].map(n=>`<button data-nav="${n}" class="${view===n?'active':''}" ${view===n?'aria-current="page"':''}>${icon(n)}<span>${n[0].toUpperCase()+n.slice(1)}</span></button>`).join('')}</nav>`;if(view==='projects'||view==='creatives')renderResults();}
function renderResults(){let list=view==='projects'?[...state.projects,...projects]:creatives;list=list.filter(p=>(!role||p.roles.includes(role))&&`${p.title||p.name} ${p.description||p.headline} ${p.roles.join(' ')} ${p.location}`.toLowerCase().includes(query.toLowerCase()));if(view==='projects'){if(category==='My projects')list=list.filter(p=>p.mine);else if(category!=='All projects')list=list.filter(p=>p.medium===category);if(savedOnly)list=list.filter(p=>state.saved.includes(p.id));}document.querySelector('#count').textContent=`${list.length} ${view==='projects'?'projects':'creatives'}`;document.querySelector('#results').innerHTML=list.length?list.map(view==='projects'?projectCard:creatorCard).join(''):'<div class="empty"><h2>A little more room to explore.</h2><p>No matches yet. Try a different role or search.</p><button class="secondary" data-action="clear">Clear filters</button></div>';}
function portfolio(){const p=state.profile;return `<div class="profile-layout"><section class="panel"><div class="creator-avatar">${esc((p.name||'You').slice(0,2).toUpperCase())}</div><h2>${esc(p.name||'Make yourself known.')}</h2><p class="intro" style="margin:0">${esc(p.headline||'Your next collaboration starts with your story.')}</p><div class="tags">${tags(p.roles||[])}</div><p>${esc(p.bio)}</p>${socialLinks(p,true)}</section><section class="panel"><h2>Your creative profile</h2><form id="profile-form"><div class="form-grid">${field('Name','name',p.name,true)}${field('Location','location',p.location)}${field('Headline','headline',p.headline,false,'text',true)}<label class="field full">About you<textarea name="bio" maxlength="3000">${esc(p.bio)}</textarea></label>${rolePicker(p.roles||[])}${socialEditor(p)}<section class="field full messaging-editor"><h3>Primary Messaging</h3><p class="section-help">Keep conversations on your preferred platform. Perception Den is for requests and invites.</p>${field("Platform or label (optional)","messagingLabel",p.messagingLabel||"",false,"text",true)}${field("Message me here — link","messagingUrl",p.messagingUrl||"",false,"url",true)}</section></div><div class="form-actions"><button class="primary">Save profile ${icon('arrow')}</button></div></form><div class="section-title"><h2>Selected work</h2><button class="secondary" data-action="add-work">${icon('plus')} Add work</button></div>${(p.works||[]).map((w,i)=>`<article class="work"><h3>${esc(w.title)}</h3><p>${esc(w.credit)}</p>${safeUrl(w.url)?`<a href="${esc(w.url)}" target="_blank" rel="noopener noreferrer">View work ↗</a>`:''}<button class="secondary" data-remove-work="${i}" aria-label="Remove ${esc(w.title)}" style="float:right;padding:7px 12px">Remove</button></article>`).join('')||'<p class="intro" style="margin:0">Add a film, track, reel, or creative project. Tell people exactly what you contributed.</p>'}</section></div>`;}
function activity(){return `<div class="chips">${['All activity','Requests','Invites'].map((x,i)=>`<button class="chip ${i===0?'active':''}" data-activity-filter="${x}">${x}</button>`).join('')}</div><div id="activity-list">${activityRows()}</div>`;}
function activityRows(filter='All activity'){const list=state.activity.filter(x=>filter==='All activity'||(filter==='Requests'?x.kind==='request':x.kind==='invite'));return list.length?list.map(x=>`<article class="activity"><div><h3>${x.kind==='request'?'Request to join':'Invitation to '+esc(x.person)} · ${esc(x.project)}</h3><p>${esc(x.role)} · ${esc(x.message)}</p><p>${new Date(x.date).toLocaleDateString()} · Local draft</p></div><button class="secondary" data-cancel="${x.id}">Remove draft</button></article>`).join(''):'<div class="empty"><h2>Your next connection is out there.</h2><p>Explore a project to request a place, or invite a creative to one of yours.</p><button class="primary" data-nav="projects">Explore projects '+icon('arrow')+'</button></div>';}
function field(label,name,value='',required=false,type='text',full=false){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="300"></label>`;}
function safeUrl(url){try{return ['http:','https:'].includes(new URL(url).protocol);}catch{return false;}}
function openModal(title,body){if(dialog.open)dialog.close();dialog.innerHTML=`<div class="dialog-top"><span>${esc(title)}</span><button class="round" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-content">${body}</div>`;dialog.setAttribute('aria-label',title);dialog.showModal();dialog.scrollTop=0;}
function projectDetail(id){const p=[...state.projects,...projects].find(p=>p.id===id);if(!p)return;openModal('Project workspace',`${cover(p)}<h2>${esc(p.title)}</h2><p>${esc(p.description)}</p><div class="tags">${tags([p.medium,p.stage,p.location,p.budget])}</div><h3>Looking for</h3><div class="tags">${tags(p.roles)}</div><p>Created by ${esc(p.owner)}${p.mine?'':' · Sample project'}</p>${socialLinks(p)}${p.mine?socialLinks({messagingUrl:state.profile.messagingUrl,messagingLabel:state.profile.messagingLabel},true):''}${projectWorkspace(p)}${p.mine?'<button class="primary" data-nav="creatives">Find collaborators '+icon('arrow')+'</button>':`<form id="request-form" data-id="${p.id}"><label class="field">How would you like to contribute?<select name="role">${p.roles.map(r=>`<option>${esc(r)}</option>`).join('')}</select></label><label class="field" style="margin-top:16px">Introduce yourself<textarea name="message" required maxlength="1500" placeholder="What excites you about this project? Share what you can bring."></textarea></label><p style="font-size:12px;margin-top:12px">Preview: this creates a local request draft. No message is sent.</p><div class="form-actions"><button class="primary">Save join request ${icon('arrow')}</button></div></form>`}`);}
function creatorDetail(id){const c=creatives.find(c=>c.id===id);if(!c)return;openModal('Creative portfolio',`${cover(c,'creator-cover')}<h2>${c.name}</h2><p>${c.headline}</p><div class="tags">${tags(c.roles)}</div><p>${c.bio}</p>${socialLinks(c,true)}<h3>Selected work</h3><article class="work"><strong>${c.work}</strong><p>${c.credit}</p><span class="tag">Illustrative portfolio entry</span></article><h3>Invite ${c.name.split(' ')[0]} to your project</h3>${state.projects.length?`<form id="invite-form" data-id="${c.id}"><label class="field">Choose your project<select name="project">${state.projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><label class="field" style="margin-top:16px">Your invitation<textarea name="message" required maxlength="1500" placeholder="Tell them why you’d love to work together."></textarea></label><p style="font-size:12px;margin-top:12px">Preview: this saves an invitation draft in this browser. No message is sent.</p><div class="form-actions"><button class="primary">Save invitation ${icon('arrow')}</button></div></form>`:'<p>Create a project first, then invite someone whose work speaks to you.</p><button class="primary" data-action="create">Create a project '+icon('plus')+'</button>'}`);}
function navigate(next){if(!currentUser){renderAuth();return;}if(dialog.open)dialog.close();view=next;query='';role='';category='All projects';savedOnly=false;location.hash=next;render();window.scrollTo({top:0,behavior:'smooth'});}
function socialRow(item={}){return `<div class="social-row"><label>Platform<select name="socialPlatform" aria-label="Social platform">${optionList(['Instagram','TikTok','YouTube','Vimeo','X','Bluesky','Facebook','LinkedIn','SoundCloud','Bandcamp','Spotify','Website','Other'],item.platform||'Instagram')}</select></label><label>Link<input name="socialUrl" aria-label="Social link" type="url" placeholder="https://…" maxlength="2000" value="${esc(item.url||'')}"></label><button type="button" class="round" data-remove-social aria-label="Remove social link">${icon('close')}</button></div>`;}
function socialEditor(value){return `<section class="field full social-editor"><h3>Social media</h3><p class="section-help">Link to the pages where people can follow ${value.mine?'this project':'your work'}.</p><div class="social-rows">${(value.socials||[]).map(socialRow).join('')}</div><button type="button" class="secondary" data-add-social>${icon('plus')} Add social link</button></section>`;}
function collectSocials(form){return [...form.querySelectorAll('.social-row')].map(row=>({platform:row.querySelector('[name=socialPlatform]').value,url:row.querySelector('[name=socialUrl]').value.trim()})).filter(x=>x.url);}
function socialLinks(value,primary=false){const socials=(value.socials||[]).filter(x=>safeUrl(x.url));return `${socials.length?`<div class="social-links" aria-label="Social media links">${socials.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.platform)} ↗</a>`).join('')}</div>`:''}${primary&&safeUrl(value.messagingUrl)?`<a class="primary message-link" href="${esc(value.messagingUrl)}" target="_blank" rel="noopener noreferrer">Message me here ${icon('arrow')}</a>${value.messagingLabel?`<p class="section-help">${esc(value.messagingLabel)}</p>`:''}`:''}`;}
function rolePicker(selected){return `<div class="field full"><span>Your creative roles</span><details class="role-picker"><summary>Select your roles <span class="role-count">${selected.length} selected</span></summary><div class="role-dropdown"><label class="search">${icon('search')}<input type="search" class="role-search" aria-label="Find a creative role" placeholder="Find a role…"></label><div class="role-bubbles">${[...new Set([...roles,...selected])].map(r=>`<label class="role-bubble"><input type="checkbox" name="profileRoles" value="${esc(r)}" ${selected.includes(r)?'checked':''}><span>${esc(r)}</span></label>`).join('')}</div><p class="role-no-results" hidden>No roles match this search.</p><button type="button" class="secondary" data-close-roles>Done</button></div></details><div class="selected-roles">${tags(selected)}</div></div>`;}
function coverEditor(p){return `<section class="field full cover-editor"><h3>Project cover</h3><img class="cover-thumbnail" src="${esc(p.cover||art.film)}" alt="Cover preview"><label class="cover-drop" tabindex="0" role="button" aria-label="Choose a cover image"><input class="sr-only" type="file" name="coverFile" accept="image/jpeg,image/png,image/webp"><strong>Drop a cover image here</strong><span>or click to choose a file · JPG, PNG, WebP · up to 10 MB</span></label><p class="cover-status section-help" role="status"></p><button type="button" class="secondary" data-reset-cover>Use default cover</button>${field('Or use a cover image URL','cover',safeUrl(p.cover)?p.cover:'',false,'url',true)}</section>`;}
async function chooseCover(form,file){if(!file)return;const status=form.querySelector('.cover-status'),token={};form.coverToken=token;form.coverBusy=true;const submit=form.querySelector('button:not([type]),button[type=submit]');if(submit)submit.disabled=true;status.textContent='Preparing your cover…';let bitmap;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Choose a JPG, PNG, or WebP image up to 10 MB.');bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#172139';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.82);if(data.length>1300000)throw Error('This image is too detailed to save locally. Choose a smaller image.');if(!form.isConnected||form.coverToken!==token)return;form.coverDraft=data;form.elements.cover.value='';form.querySelector('.cover-thumbnail').src=data;status.textContent=`${file.name} · Ready to save`; }catch(error){if(form.isConnected&&form.coverToken===token)status.textContent=error.message;}finally{bitmap?.close();if(form.coverToken===token){form.coverBusy=false;if(submit)submit.disabled=false;}}}
// Social links and role selections remain form drafts until Save is pressed.
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-add-social')){const editor=button.closest('.social-editor');if(editor.querySelectorAll('.social-row').length>=10)return toast('You can add up to 10 social links.');editor.querySelector('.social-rows').insertAdjacentHTML('beforeend',socialRow());editor.querySelector('.social-row:last-child input').focus();}if(button.hasAttribute('data-remove-social'))button.closest('.social-row').remove();if(button.hasAttribute('data-close-roles'))button.closest('details').open=false;if(button.hasAttribute('data-reset-cover')){const form=button.closest('form');form.coverToken={};form.coverDraft='';form.coverBusy=false;form.elements.cover.value='';form.querySelector('.cover-thumbnail').src=art[form.elements.medium.value==='Music'?'music':form.elements.medium.value==='Animation'?'light':'film'];form.querySelector('.cover-status').textContent='Default cover selected. Save to apply.';form.querySelector('button:not([type]),button[type=submit]').disabled=false;}});
document.addEventListener('change',e=>{const input=e.target;if(input.name==='coverFile')void chooseCover(input.form,input.files[0]);if(input.name==='profileRoles'){const picker=input.closest('.role-picker'),checked=[...picker.querySelectorAll('input:checked')].map(x=>x.value);picker.querySelector('.role-count').textContent=`${checked.length} selected`;picker.parentElement.querySelector('.selected-roles').innerHTML=tags(checked);}});
document.addEventListener('input',e=>{if(e.target.classList.contains('role-search')){const picker=e.target.closest('.role-picker'),q=e.target.value.toLowerCase();let count=0;picker.querySelectorAll('.role-bubble').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(q);if(!el.hidden)count++;});picker.querySelector('.role-no-results').hidden=count>0;}if(e.target.name==='cover'){const form=e.target.form;form.coverToken={};form.coverBusy=false;form.coverDraft=undefined;form.querySelector('button:not([type]),button[type=submit]').disabled=false;form.querySelector('.cover-status').textContent='';if(safeUrl(e.target.value))form.querySelector('.cover-thumbnail').src=e.target.value;}});
for(const event of ['dragover','dragleave','drop'])document.addEventListener(event,e=>{const zone=e.target.closest('.cover-drop');if(!zone)return;e.preventDefault();zone.classList.toggle('dragging',event==='dragover');if(event==='drop')void chooseCover(zone.closest('form'),e.dataTransfer.files[0]);});
document.addEventListener('keydown',e=>{if(e.target.matches('.cover-drop')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.querySelector('input').click();}if(e.key==='Escape'){const open=document.querySelector('.role-picker[open]');if(open){open.open=false;open.querySelector('summary').focus();}}});

function renderAuth(){
 const signup=authMode==='signup';document.body.classList.add('signed-out');
 app.innerHTML=`<div class="auth-shell"><header class="auth-brand brand">${icon('orbit')}<span>perception den</span></header><main class="auth-layout"><section class="auth-story"><span class="auth-kicker">GOOD THINGS START WITH PEOPLE</span><h1>Your next<br>great thing.<br><em>Starts here.</em></h1><p>A home for your ideas.<br>A place to find your people.</p><div class="auth-art" aria-hidden="true"><div class="auth-orbit orbit-one"></div><div class="auth-orbit orbit-two"></div><div class="auth-core">${icon('orbit')}</div><span class="craft-bubble bubble-film">${icon('projects')} Film</span><span class="craft-bubble bubble-sound">♫ Sound</span><span class="craft-bubble bubble-music">♪ Music</span><span class="craft-bubble bubble-you">Your next collaboration ↗</span></div></section><section class="auth-panel" aria-labelledby="auth-title"><div class="auth-tabs" aria-label="Account options"><button type="button" data-auth-mode="signin" class="${signup?'':'active'}" aria-pressed="${!signup}">Sign in</button><button type="button" data-auth-mode="signup" class="${signup?'active':''}" aria-pressed="${signup}">Create account</button></div><div class="auth-greeting">${icon(signup?'plus':'orbit')}</div><h2 id="auth-title">${signup?'Make yourself at home.':'Welcome to your den.'}</h2><p class="auth-subtitle">${signup?'A little about you. A whole world of possibilities.':'Your ideas, your projects, your people.'}</p><form id="auth-form"><fieldset><label class="auth-field">Username<input name="username" aria-label="Username" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Your creative name" required minlength="3" maxlength="24" ${signup?'pattern="[a-zA-Z0-9_.-]{3,24}"':''}></label>${signup?'<label class="auth-field">Email<input name="email" aria-label="Email" type="email" autocomplete="email" autocapitalize="none" placeholder="you@example.com" required maxlength="254"><small>For future verification and account recovery. No email is sent yet.</small></label>':''}<label class="auth-field">Password<span class="password-wrap"><input id="auth-password" name="password" aria-label="Password" type="password" autocomplete="${signup?'new-password':'current-password'}" placeholder="${signup?'Make it at least 8 characters':'Enter your password'}" required ${signup?'minlength="8"':''} maxlength="128"><button type="button" data-show-password aria-label="Show password" aria-pressed="false">Show</button></span>${signup?'<small>8 or more characters. Make it yours.</small>':''}</label>${signup&&account.hasLegacyWorkspace()?'<label class="import-workspace"><input type="checkbox" name="importWorkspace" checked><span>Bring my existing local projects and portfolio into this account.</span></label>':''}<p id="auth-error" class="auth-error" role="alert" tabindex="-1" hidden></p><button type="submit" class="auth-submit">${signup?'Create my account':'Sign in'} ${icon('arrow')}</button></fieldset></form><p class="auth-switch">${signup?'Already part of the den?':'New around here?'} <button type="button" data-auth-mode="${signup?'signin':'signup'}">${signup?'Sign in':'Create an account'}</button></p><div class="auth-preview-note"><span class="preview-dot"></span><p><strong>Account preview</strong>Saved on this device for now. Use a test password.<br>Cloud accounts and email verification come next.</p></div></section></main><footer class="auth-footer">Independent ideas. Shared possibilities.</footer></div>`;
}
function enterAccount(user){currentUser=user;state=account.loadWorkspace(user);document.body.classList.remove('signed-out');view=['projects','creatives','activity','portfolio'].includes(location.hash.slice(1))?location.hash.slice(1):'projects';query='';role='';category='All projects';savedOnly=false;render();window.scrollTo({top:0});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.authMode&&!authBusy){authMode=b.dataset.authMode;renderAuth();}if(b.hasAttribute('data-show-password')){const input=document.querySelector('#auth-password');const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',show?'Hide password':'Show password');b.setAttribute('aria-pressed',String(show));}if(b.hasAttribute('data-sign-out')){try{account.signOut();currentUser=null;state=emptyWorkspace();document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.body.classList.remove('role-dialog-open');document.querySelector('#toast').classList.remove('visible');authMode='signin';location.hash='';render();window.scrollTo({top:0});}catch{toast('Could not sign out. Please try again.');}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();if(authBusy)return;const form=e.target,fd=new FormData(form),error=form.querySelector('#auth-error'),submit=form.querySelector('[type=submit]');error.hidden=true;authBusy=true;form.querySelector('fieldset').disabled=true;submit.textContent=authMode==='signup'?'Creating your den…':'Signing in…';document.querySelectorAll('[data-auth-mode]').forEach(b=>b.disabled=true);try{const result=await account[authMode==='signup'?'signUp':'signIn']({username:fd.get('username'),email:fd.get('email'),password:fd.get('password'),importWorkspace:fd.get('importWorkspace')==='on'});form.reset();enterAccount(result.user);if(result.imported)toast('Your existing projects and portfolio are now in this preview account.');}catch(err){error.textContent=err.message||'We couldn’t sign you in. Please try again.';error.hidden=false;error.focus();form.querySelector('fieldset').disabled=false;submit.innerHTML=(authMode==='signup'?'Create my account':'Sign in')+' '+icon('arrow');document.querySelectorAll('[data-auth-mode]').forEach(b=>b.disabled=false);}finally{authBusy=false;}});

// Project records are shared by discovery and portfolio. IDs stay stable across edits.
function ownedProject(id){return state.projects.find(p=>p.id===id&&p.mine);}
function commitWorkspace(change){const previous=structuredClone(state);change();if(!persist()){state=previous;toast("Could not save. Browser storage is full or unavailable; your previous data is unchanged.");return false;}return true;}
function myProjects(){return `<section class="my-projects" aria-labelledby="my-projects-title"><div class="section-title"><div><p class="eyebrow">Ideas you’re bringing to life</p><h2 id="my-projects-title">My Projects</h2></div><button class="secondary" data-action="create">${icon('plus')} New project</button></div><div class="grid">${state.projects.filter(p=>p.mine).map(p=>`<article class="card interactive-card"><button class="card-open" data-project="${p.id}" aria-label="Open ${esc(p.title)}"></button>${cover(p)}<div class="card-body"><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="tags">${tags(p.roles)}</div><div class="project-stats"><span>${(p.members||[]).length} collaborators</span><span>${(p.media||[]).length} work items</span></div><div class="owner-actions"><button class="primary" data-project="${p.id}">Open workspace ${icon('arrow')}</button><button class="secondary" data-edit-project="${p.id}">Edit preview</button><button class="danger" data-delete-project="${p.id}">Delete</button></div></div></article>`).join('')||`<div class="empty"><h3>A home for your next idea.</h3><p>Create a project to build your team and share work in progress.</p><button class="primary" data-action="create">Create a project ${icon('plus')}</button></div>`}</div></section>`;}
function optionList(items,value){return [...new Set([...items,value].filter(Boolean))].map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');}
function createProject(id){const p=id?ownedProject(id):null;if(id&&!p)return;const v=p||{};openModal(p?'Edit preview':'Make room for your idea',`<h2>${p?'Keep your project moving.':'What are you making?'}</h2><p>${p?'Changes appear in My Projects and project discovery.':'A clear vision helps the right people find you.'}</p><form id="project-form" data-edit-id="${p?.id||''}"><div class="form-grid">${field('Project title','title',v.title||'',true,'text',true)}<label class="field">Project type<select name="medium">${optionList(['Film','Music','Animation'],v.medium||'Film')}</select></label><label class="field">Stage<select name="stage">${optionList(['Development','Pre-production','In production','Post-production'],v.stage||'Development')}</select></label><label class="field full">The idea<textarea name="description" required maxlength="3000" placeholder="Tell us the story you want to bring to life.">${esc(v.description||'')}</textarea></label>${field('Roles needed (comma separated)','roles',(v.roles||[]).join(', '),true,'text',true)}${field('Location or remote','location',v.location||'Remote',true)}<label class="field">Collaboration terms<select name="budget">${optionList(['Paid collaboration','Creative partnership','Terms to discuss'],v.budget||'Paid collaboration')}</select></label>${coverEditor(v)}${socialEditor({...v,mine:true})}</div><div class="form-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary">${p?'Save changes':'Create project'} ${icon('arrow')}</button></div></form>`);}
function memberTag(m){return `<span class="member-tag"><span class="member-initial">${esc(m.name.slice(0,1).toUpperCase())}</span><span><strong>${esc(m.name)}</strong><small>${esc(m.role)}</small></span></span>`;}
function projectWorkspace(p){const members=p.members||[],media=p.media||[];return `<section class="workspace-section"><div class="section-title"><h3>On this project</h3>${p.mine?`<button class="secondary" data-add-member="${p.id}">${icon('plus')} Add collaborator</button>`:''}</div><p class="section-help">${p.mine?'List the people already working with you. Invitations stay separate.':'The team behind this project.'}</p><div class="member-list">${members.map(m=>`<div class="member-row">${safeUrl(m.url)?`<a href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">${memberTag(m)}</a>`:memberTag(m)}${p.mine?`<button class="round" data-remove-member="${m.id}" data-owner="${p.id}" aria-label="Remove ${esc(m.name)} from project">${icon('close')}</button>`:''}</div>`).join('')||'<p class="workspace-empty">No collaborators listed yet.</p>'}</div></section><section class="workspace-section"><div class="section-title"><div><h3>Work in progress</h3><p class="section-help">Pictures, cuts, references, and the latest version.</p></div>${p.mine?`<button class="secondary" data-add-media="${p.id}">${icon('plus')} Add work</button>`:''}</div><div class="media-grid">${media.map(m=>mediaCard(p,m)).join('')||'<p class="workspace-empty">Give your team something to build on. Add an image, video, or project link.</p>'}</div>${p.mine?'<p class="section-help local-boundary">Saved in this browser. Shared team access comes with the backend.</p>':''}</section>${p.mine?`<div class="workspace-actions"><button class="secondary" data-edit-project="${p.id}">Edit preview</button><button class="danger" data-delete-project="${p.id}">Delete project</button></div>`:''}`;}
function mediaCard(p,m){if(!safeUrl(m.url))return '';const credit=(p.members||[]).filter(x=>(m.memberIds||[]).includes(x.id));let preview='';if(m.type==='Image')preview=`<a class="media-preview" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer"><img src="${esc(m.url)}" alt="${esc(m.title)}" loading="lazy"></a>`;else if(m.type==='Video'&&/\.(mp4|webm|ogv)(?:[?#]|$)/i.test(m.url))preview=`<video class="media-preview" controls preload="metadata" aria-label="${esc(m.title)}"><source src="${esc(m.url)}">Your browser cannot play this video. Use the source link below.</video>`;else preview=`<a class="media-link-preview" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">${icon(m.type==='Video'?'projects':'arrow')}<span>${m.type==='Video'?'Watch video':'Open reference'}</span></a>`;return `<article class="media-card">${preview}<div class="media-body"><span class="tag">${esc(m.type)}</span><h4>${esc(m.title)}</h4>${m.notes?`<p>${esc(m.notes)}</p>`:''}<div class="tags">${credit.map(x=>`<span class="tag">@${esc(x.name)}</span>`).join('')}</div><div class="media-actions"><a href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>${p.mine?`<button class="danger" data-remove-media="${m.id}" data-owner="${p.id}">Remove</button>`:''}</div></div></article>`;}
function addMember(id){const p=ownedProject(id);if(!p)return;openModal('Project collaborators',`<h2>Who’s making it with you?</h2><p>Add someone who is already part of ${esc(p.title)}. This creates a project credit, not an invitation or account.</p><form id="member-form" data-owner="${p.id}"><div class="form-grid">${field('Collaborator name','name','',true,'text',true)}${field('Role on this project','role','',true,'text',true)}${field('Portfolio or profile link (optional)','url','',false,'url',true)}</div><div class="form-actions"><button type="button" class="secondary" data-project="${p.id}">Back to project</button><button class="primary">Add collaborator ${icon('plus')}</button></div></form>`);}
function addMedia(id){const p=ownedProject(id);if(!p)return;openModal('Project work',`<h2>Bring the work into view.</h2><p>Add a picture, video, or link for ${esc(p.title)}.</p><form id="media-form" data-owner="${p.id}"><div class="form-grid">${field('Title','title','',true,'text',true)}<label class="field full">Type<select name="type" aria-label="Type"><option>Image</option><option>Video</option><option>Link</option></select></label>${field('Media or project URL','url','',true,'url',true)}<p class="field full section-help">Use a direct image URL for pictures. MP4 and WebM videos play here; YouTube, Vimeo, and other pages open at their source.</p><label class="field full">Notes or version<textarea name="notes" maxlength="2000" placeholder="Rough cut v2, updated storyboards, a reference for the sound…"></textarea></label><fieldset class="field full member-picker"><legend>Tag collaborators on this work</legend>${(p.members||[]).map(m=>`<label><input type="checkbox" name="memberIds" value="${m.id}"><span>${esc(m.name)} <small>${esc(m.role)}</small></span></label>`).join('')||'<p>Add your current collaborators to the project first to tag them here.</p>'}</fieldset></div><div class="form-actions"><button type="button" class="secondary" data-project="${p.id}">Back to project</button><button class="primary">Add to project ${icon('plus')}</button></div></form>`);}
function confirmProjectDelete(id){const p=ownedProject(id);if(!p)return;openModal('Delete project',`<h2>Delete “${esc(p.title)}”?</h2><p>This removes the project from your portfolio and discovery, along with its collaborator credits, work items, saved bookmark, and invitation drafts. Your original media files and links are unaffected.</p><div class="form-actions"><button class="secondary" data-project="${p.id}">Keep project</button><button class="danger danger-solid" data-confirm-delete="${p.id}">Delete project</button></div>`);}
// Handle workspace actions before the original app's general event handlers.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;const handled=['editProject','deleteProject','confirmDelete','addMember','addMedia','removeMember','removeMedia'].some(k=>d[k]!==undefined);if(!handled)return;e.stopImmediatePropagation();if(d.editProject)return createProject(d.editProject);if(d.deleteProject)return confirmProjectDelete(d.deleteProject);if(d.addMember)return addMember(d.addMember);if(d.addMedia)return addMedia(d.addMedia);if(d.confirmDelete){const p=ownedProject(d.confirmDelete);if(!p)return;if(!commitWorkspace(()=>{state.projects=state.projects.filter(x=>x.id!==p.id);state.saved=state.saved.filter(x=>x!==p.id);state.activity=state.activity.filter(x=>x.projectId!==p.id);}))return;dialog.close();render();toast('Project deleted from your portfolio and discovery.');return;}const p=ownedProject(d.owner);if(!p)return;if(d.removeMember){if(!commitWorkspace(()=>{p.members=(p.members||[]).filter(x=>x.id!==d.removeMember);for(const m of p.media||[])m.memberIds=(m.memberIds||[]).filter(x=>x!==d.removeMember);}))return;}if(d.removeMedia){if(!commitWorkspace(()=>{p.media=(p.media||[]).filter(x=>x.id!==d.removeMedia);}))return;}render();projectDetail(p.id);});
document.addEventListener('submit',e=>{const f=e.target;if(!['project-form','member-form','media-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();const fd=new FormData(f),data=Object.fromEntries(fd);for(const k of Object.keys(data))if(typeof data[k]==='string')data[k]=data[k].trim();if(f.id==='project-form'){const previous=f.dataset.editId?ownedProject(f.dataset.editId):null;if(f.dataset.editId&&!previous)return toast('This project is no longer available.');if(f.coverBusy)return toast('Wait for your cover image to finish preparing.');const socials=collectSocials(f);if(socials.some(x=>!safeUrl(x.url)))return toast('Use an http or https social link.');delete data.coverFile;delete data.socialPlatform;delete data.socialUrl;if(!data.title||!data.description||!data.roles)return toast('Add a title, idea, and at least one role.');if(data.cover&&!safeUrl(data.cover))return toast('Use an http or https image link.');const next={...previous,...data,id:previous?.id||crypto.randomUUID(),roles:data.roles.split(',').map(x=>x.trim()).filter(Boolean),cover:(f.coverDraft!==undefined?f.coverDraft:data.cover||(previous?.cover?.startsWith('data:image/jpeg;base64,')?previous.cover:''))||art[data.medium==='Music'?'music':data.medium==='Animation'?'light':'film'],socials,owner:state.profile.name||'You',mine:true,members:previous?.members||[],media:previous?.media||[],updatedAt:new Date().toISOString()};if(!next.roles.length)return toast('Add at least one role.');if(!commitWorkspace(()=>{if(previous){state.projects=state.projects.map(x=>x.id===next.id?next:x);state.activity=state.activity.map(x=>x.projectId===next.id?{...x,project:next.title}:x);}else state.projects.unshift(next);}))return;dialog.close();render();if(previous)projectDetail(next.id);toast(previous?'Project updated everywhere.':'Project created. Find it in your portfolio under My Projects.');return;}const p=ownedProject(f.dataset.owner);if(!p)return toast('This project is no longer available.');if(data.url&&!safeUrl(data.url))return toast('Use an http or https link.');if(f.id==='member-form'){if(!data.name||!data.role)return toast('Add a name and project role.');if((p.members||[]).some(x=>x.name.toLowerCase()===data.name.toLowerCase()))return toast('This collaborator is already listed.');if(!commitWorkspace(()=>{p.members=[...p.members||[],{id:crypto.randomUUID(),name:data.name,role:data.role,url:data.url}];}))return;}else{if(!data.title||!data.url||!['Image','Video','Link'].includes(data.type))return toast('Add a title, type, and valid link.');const memberIds=fd.getAll('memberIds').filter(id=>(p.members||[]).some(m=>m.id===id));if(!commitWorkspace(()=>{p.media=[...p.media||[],{id:crypto.randomUUID(),title:data.title,type:data.type,url:data.url,notes:data.notes,memberIds,createdAt:new Date().toISOString()}];}))return;}render();projectDetail(p.id);});

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.nav)return navigate(d.nav);if(d.project)return projectDetail(d.project);if(d.creator)return creatorDetail(d.creator);if(d.save){state.saved=state.saved.includes(d.save)?state.saved.filter(x=>x!==d.save):[...state.saved,d.save];persist();render();if(dialog.open){b.classList.toggle('saved',state.saved.includes(d.save));b.setAttribute('aria-pressed',state.saved.includes(d.save));}return;}if(d.category){category=d.category;render();return;}if(d.activityFilter){document.querySelectorAll('[data-activity-filter]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#activity-list').innerHTML=activityRows(d.activityFilter);return;}if(d.cancel){state.activity=state.activity.filter(x=>x.id!==d.cancel);persist();render();return;}if(d.removeWork!==undefined){state.profile.works.splice(Number(d.removeWork),1);persist();render();return;}if(d.action==='close')dialog.close();if(d.action==='create'){if(dialog.open)dialog.close();createProject();}if(d.action==='clear'){query='';role='';category='All projects';savedOnly=false;render();}if(d.action==='saved'){savedOnly=!savedOnly;render();}if(d.action==='add-work')openModal('Add to your portfolio',`<h2>Let your work speak.</h2><form id="work-form"><div class="form-grid">${field('Project title','title','',true,'text',true)}${field('Your contribution / credit','credit','',true,'text',true)}${field('Link to your work','url','',true,'url',true)}</div><div class="form-actions"><button class="primary">Add work ${icon('plus')}</button></div></form>`);});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderResults();}});document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;renderResults();}});
document.addEventListener('submit',e=>{const form=e.target;if(!['profile-form','work-form','request-form','invite-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));if(form.id==='profile-form'){const socials=collectSocials(form),messagingUrl=data.messagingUrl.trim();if(socials.some(x=>!safeUrl(x.url))||(messagingUrl&&!safeUrl(messagingUrl)))return toast('Use an http or https link.');const selected=new FormData(form).getAll('profileRoles');if(!commitWorkspace(()=>{state.profile={...state.profile,name:data.name.trim(),location:data.location.trim(),headline:data.headline.trim(),bio:data.bio.trim(),roles:selected,socials,messagingUrl,messagingLabel:data.messagingLabel.trim()};}))return;render();toast('Your portfolio is saved in this browser.');return;}if(form.id==='work-form'){if(!safeUrl(data.url))return toast('Use an http or https portfolio link.');state.profile.works.push(data);persist();dialog.close();render();return;}const request=form.id==='request-form';const p=request?projects.find(x=>x.id===form.dataset.id):state.projects.find(x=>x.id===data.project);const c=request?null:creatives.find(x=>x.id===form.dataset.id);if(!data.message.trim())return toast('Add a short introduction.');if(state.activity.some(x=>x.kind===(request?'request':'invite')&&x.projectId===p.id&&x.person===(c?.name||'')))return toast('You already have a draft for this connection.');state.activity.unshift({id:crypto.randomUUID(),kind:request?'request':'invite',projectId:p.id,project:p.title,person:c?.name||'',role:data.role||c.roles[0],message:data.message,date:new Date().toISOString()});persist();dialog.close();navigate('activity');toast('Draft saved. Real delivery comes with the backend.');});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['projects','creatives','activity','portfolio'].includes(next)&&next!==view)navigate(next);});
render();



// Native desktop select; touch-friendly mobile dialog with its own scrolling list.
const mobileRoleDialog=document.createElement('dialog');
mobileRoleDialog.id='mobile-role-dialog';mobileRoleDialog.setAttribute('aria-labelledby','mobile-role-title');document.body.append(mobileRoleDialog);
function openMobileRoles(){mobileRoleDialog.innerHTML=`<header class="mobile-role-header"><div><h2 id="mobile-role-title">Choose a creative role</h2><p>Find the people or projects you’re looking for.</p></div><button type="button" class="round" data-close-role-filter aria-label="Close role picker">${icon('close')}</button></header><label class="mobile-role-search">${icon('search')}<input type="search" id="mobile-role-search" aria-label="Search creative roles" placeholder="Search roles…" autocomplete="off"></label><div class="mobile-role-options" role="group" aria-label="Creative roles">${['',...roles].map(r=>`<button type="button" class="mobile-role-option" data-filter-role="${esc(r)}" aria-pressed="${role===r}"><span>${esc(r||'All creative roles')}</span><span aria-hidden="true">${role===r?'✓':''}</span></button>`).join('')}</div><p class="mobile-role-empty" hidden>No roles found. Try another search.</p>`;mobileRoleDialog.showModal();document.body.classList.add('role-dialog-open');mobileRoleDialog.querySelector('[data-close-role-filter]').focus();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-open-role-filter'))openMobileRoles();if(b.hasAttribute('data-close-role-filter'))mobileRoleDialog.close();if(b.hasAttribute('data-filter-role')){role=b.dataset.filterRole;render();mobileRoleDialog.close();}});
mobileRoleDialog.addEventListener('close',()=>{document.body.classList.remove('role-dialog-open');document.querySelector('[data-open-role-filter]')?.focus();});
mobileRoleDialog.addEventListener('input',e=>{if(e.target.id!=='mobile-role-search')return;const q=e.target.value.trim().toLowerCase();let count=0;mobileRoleDialog.querySelectorAll('[data-filter-role]').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(q);if(!b.hidden)count++;});mobileRoleDialog.querySelector('.mobile-role-empty').hidden=count>0;mobileRoleDialog.querySelector('.mobile-role-options').scrollTop=0;});
